import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.Crpw6aS5.js";const g=JSON.parse('{"title":"格雷格·阿贝尔","description":"","frontmatter":{"title":"格雷格·阿贝尔"},"headers":[],"relativePath":"04_people/格雷格·阿贝尔.md","filePath":"04_people/格雷格·阿贝尔.md"}'),l={name:"04_people/格雷格·阿贝尔.md"};function i(h,t,n,s,d,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="格雷格·阿贝尔-gregory-w-abel" tabindex="-1">格雷格·阿贝尔（Gregory W. Abel） <a class="header-anchor" href="#格雷格·阿贝尔-gregory-w-abel" aria-label="Permalink to &quot;格雷格·阿贝尔（Gregory W. Abel）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>全名</strong></td><td>Gregory Warren Abel</td></tr><tr><td><strong>出生日期</strong></td><td>1961年</td></tr><tr><td><strong>出生地</strong></td><td>加拿大埃德蒙顿</td></tr><tr><td><strong>公司</strong></td><td><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a>、<a href="/03_companies/中美能源.html">中美能源</a>（BHE）</td></tr><tr><td><strong>职位</strong></td><td>伯克希尔副董事长（非保险业务）；2025年起任 CEO</td></tr><tr><td><strong>任期</strong></td><td>2021年1月起任副董事长；2025年5月起接任 CEO</td></tr></tbody></table><h2 id="职业生涯" tabindex="-1">职业生涯 <a class="header-anchor" href="#职业生涯" aria-label="Permalink to &quot;职业生涯&quot;">​</a></h2><h3 id="早年经历" tabindex="-1">早年经历 <a class="header-anchor" href="#早年经历" aria-label="Permalink to &quot;早年经历&quot;">​</a></h3><p>阿贝尔在加拿大成长，毕业于阿尔伯塔大学（University of Alberta），获得会计学位，后取得注册会计师（CA）资格。早年曾在普华永道（PricewaterhouseCoopers）从事审计工作，积累了扎实的财务基础。</p><h3 id="加入中美能源" tabindex="-1">加入中美能源 <a class="header-anchor" href="#加入中美能源" aria-label="Permalink to &quot;加入中美能源&quot;">​</a></h3><p>1992年，阿贝尔加入中美能源控股公司（MidAmerican Energy Holdings，后更名为 Berkshire Hathaway Energy，简称 BHE），从财务高管起步。他以出色的运营能力和资本配置眼光，逐步晋升为公司 CEO，带领 BHE 从一家区域电力公司发展为横跨能源、公用事业、管道、可再生能源的综合性能源巨头。</p><h3 id="伯克希尔的崛起" tabindex="-1">伯克希尔的崛起 <a class="header-anchor" href="#伯克希尔的崛起" aria-label="Permalink to &quot;伯克希尔的崛起&quot;">​</a></h3><p><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a>于1999年首次入股中美能源，<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>与<a href="/04_people/查理·芒格.html">查理·芒格</a>对阿贝尔的管理能力印象深刻。此后 BHE 在其领导下持续扩张：</p><ul><li>收购 PacifiCorp（美国西部大型电力公司）</li><li>大举投资风能、太阳能等可再生能源</li><li>收购 NV Energy（内华达州公用事业）</li><li>管理超过百亿美元的资本支出项目</li></ul><p>2018年，阿贝尔晋升为伯克希尔副董事长，负责监管所有<strong>非保险业务</strong>子公司，包括 BNSF 铁路、BHE、伯克希尔旗下工业与零售板块等数十家子公司。</p><h2 id="核心角色" tabindex="-1">核心角色 <a class="header-anchor" href="#核心角色" aria-label="Permalink to &quot;核心角色&quot;">​</a></h2><h3 id="为何被视为接班人" tabindex="-1">为何被视为接班人 <a class="header-anchor" href="#为何被视为接班人" aria-label="Permalink to &quot;为何被视为接班人&quot;">​</a></h3><p>2021年5月，<a href="/04_people/查理·芒格.html">查理·芒格</a>在股东大会上无意中透露&quot;Greg（阿贝尔）将接替沃伦&quot;，随后巴菲特正式确认：格雷格·阿贝尔是伯克希尔的既定接班人。</p><p>巴菲特选择阿贝尔的核心理由：</p><ol><li><strong>运营能力卓越</strong>：在极度复杂的能源与基础设施领域，长期保持高效运营与合理资本回报</li><li><strong>文化契合</strong>：深刻理解并践行伯克希尔&quot;买入并持有、充分授权管理层&quot;的文化</li><li><strong>资本配置能力</strong>：能够识别大型项目中的风险与回报，具备与巴菲特相似的长期视角</li><li><strong>低调务实</strong>：不谋求媒体曝光，专注执行，与伯克希尔风格高度一致</li></ol><h3 id="主管业务范围" tabindex="-1">主管业务范围 <a class="header-anchor" href="#主管业务范围" aria-label="Permalink to &quot;主管业务范围&quot;">​</a></h3><p>作为非保险业务副董事长，阿贝尔监管的核心版块包括：</p><table tabindex="0"><thead><tr><th>板块</th><th>代表企业</th></tr></thead><tbody><tr><td><strong>能源与公用事业</strong></td><td>Berkshire Hathaway Energy（BHE）</td></tr><tr><td><strong>铁路运输</strong></td><td>BNSF Railway</td></tr><tr><td><strong>制造业</strong></td><td>IMC、Precision Castparts、ISCAR 等</td></tr><tr><td><strong>零售与服务</strong></td><td>See&#39;s Candies、Nebraska Furniture Mart、Dairy Queen 等</td></tr><tr><td><strong>建筑与房地产</strong></td><td>Clayton Homes、Johns Manville 等</td></tr></tbody></table><h2 id="投资风格与特点" tabindex="-1">投资风格与特点 <a class="header-anchor" href="#投资风格与特点" aria-label="Permalink to &quot;投资风格与特点&quot;">​</a></h2><ul><li><strong>资本密集型项目的驾驭者</strong>：在监管严格、资本支出巨大的能源行业游刃有余，擅长长周期回报评估</li><li><strong>可再生能源先行者</strong>：在巴菲特的支持下，BHE 成为全美最大的可再生能源投资者之一，深刻理解能源转型趋势</li><li><strong>运营而非投机</strong>：风格偏向深度运营管理，而非纯粹的金融套利，与芒格所倡导的&quot;优秀企业合理价格&quot;路线契合</li><li><strong>稳健低调</strong>：极少公开接受采访，聚焦企业本身，不炒作个人形象</li></ul><h2 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h2><p>巴菲特与阿贝尔合作逾二十年，关系亦师亦友。巴菲特多次在股东信和公开场合盛赞其管理才能：</p><blockquote><p>&quot;Greg Abel 在能源领域表现出的判断力令我印象深刻。他理解如何以合理的资本回报运营复杂的受监管业务。&quot;</p></blockquote><p>2021年芒格&quot;失口&quot;确认接班事宜后，巴菲特随即补充，阿贝尔完全理解并认同伯克希尔的文化——这是巴菲特认为比财务才能更为关键的特质。</p><p>2025年5月，在伯克希尔年度股东大会上，巴菲特正式宣布退休，格雷格·阿贝尔正式接任伯克希尔哈撒韦 CEO，成为这家市值逾万亿美元企业的新掌舵人。</p><h2 id="股东信中的相关描述" tabindex="-1">股东信中的相关描述 <a class="header-anchor" href="#股东信中的相关描述" aria-label="Permalink to &quot;股东信中的相关描述&quot;">​</a></h2><p><strong>2014年股东信（致股东的信）：</strong></p><blockquote><p>&quot;在 Berkshire Hathaway Energy，Greg Abel 以出色的资本配置能力管理着我们的能源资产，并以长期视角推进可再生能源投资。&quot;</p></blockquote><p><strong>2020年股东信：</strong></p><blockquote><p>&quot;Greg 和 Ajit 每人都管理着相当于财富100强规模的业务板块，他们对伯克希尔的贡献远超我所能在一封信中充分表达的。&quot;</p></blockquote><p><strong>2023年股东信：</strong></p><blockquote><p>&quot;Greg Abel 对我们每一项非保险业务了如指掌，并在各方面充分体现了伯克希尔的价值观。他已做好准备，在明天就接任 CEO。&quot;</p></blockquote><h2 id="关联年份" tabindex="-1">关联年份 <a class="header-anchor" href="#关联年份" aria-label="Permalink to &quot;关联年份&quot;">​</a></h2><p>2000, 2014, 2018, 2020, 2021, 2023, 2025</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> - 母公司</li><li><a href="/03_companies/中美能源.html">中美能源</a>（BHE）- 长期执掌的能源旗舰</li><li><a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a> - 前任 CEO、导师</li><li><a href="/04_people/查理·芒格.html">查理·芒格</a> - 前副董事长</li><li><a href="./阿吉特·贾恩.html">阿吉特·贾恩</a> - 保险业务副董事长</li></ul><hr><p><em>最后更新：2026-04-12</em></p><h2 id="相关信件" tabindex="-1">相关信件 <a class="header-anchor" href="#相关信件" aria-label="Permalink to &quot;相关信件&quot;">​</a></h2><ul><li><a href="./../01_letters/2014年/翻译.html">2014年</a></li><li><a href="./../01_letters/2018年/翻译.html">2018年</a></li><li><a href="./../01_letters/2020年/翻译.html">2020年</a></li><li><a href="./../01_letters/2021年/翻译.html">2021年</a></li><li><a href="./../01_letters/2023年/翻译.html">2023年</a></li><li><a href="./../01_letters/2025年/翻译.html">2025年</a></li></ul>',42)])])}const c=a(l,[["render",i]]);export{g as __pageData,c as default};
